typedef struct { const char *id; void (*destroy)(void *self); } extension;
typedef struct { extension base; size_t (*word_count)(void *self); } text_accessor;

text_accessor *ta = query_interface(component, TEXT_ACCESSOR_ID);   /* NULL if unsupported */
if (ta) printf("%zu words\n", ta->word_count(component));

